const BlockType = require('../../extension-support/block-type')
const ArgumentType = require('../../extension-support/argument-type');
const formatMessage = require('format-message');
const PlayIoT = require('./playiot.js')

const blockIconURI = 'data:image/svg+xml;base64,';

const PlayIoTButtons = {
    A: 'A',
    B: 'B',
    ANY: 'any'
};

const PlayIoTMotors = {
    M1p: 'M1+',
    M1m: 'M1-',
    M2p: 'M2+',
    M2m: 'M2-'
};

const PlayIoTGPIO = {
    GPIO0: 'GPIO0',
    GPIO1: 'GPIO1',
    GPIO2: 'GPIO2',
    GPIO3: 'GPIO3'
};

/**
 * Enum for micro:bit pin states.
 * @readonly
 * @enum {string}
 */
const PlayIoTPinState = {
    ON: 'on',
    OFF: 'off'
};

/*
* Clase que crea los bloques, con sus argumentos y menus
* @author ibrahdz
*
*/    
class Scratch3PlayIoTBlocks{
    /**
     * @return {string} - the name of this extension.
     */
    static get EXTENSION_NAME () {
        return 'PlayIoT';
    }
    /**
     * @return {string} - the ID of this extension.
     */
    static get EXTENSION_ID () {
        return 'playiot';
    }

    /**
     * @return {array} - text and values for each buttons menu element
     */
    get BUTTONS_MENU () {
        return [
            {text: 'A', value: PlayIoTButtons.A},
            {text: 'B', value: PlayIoTButtons.B},
            {text: 'any', value: PlayIoTButtons.ANY}
        ];
    }

    /**
     * @return {array} - text and values for each pin state menu element
     */
    get PIN_STATE_MENU () {
        return [
            {
                text: formatMessage({
                    id: 'microbit.pinStateMenu.on',
                    default: 'on',
                    description: 'label for on element in pin state picker for micro:bit extension'
                }),
                value: PlayIoTPinState.ON
            },
            {
                text: formatMessage({
                    id: 'microbit.pinStateMenu.off',
                    default: 'off',
                    description: 'label for off element in pin state picker for micro:bit extension'
                }),
                value: PlayIoTPinState.OFF
            }
        ];
    }

    /**
     * @return {array} - text and values for each motors menu element
     */
    get MOTORS_MENU () {
        return [
            {text: 'M1+', value: PlayIoTMotors.M1p},
            {text: 'M1-', value: PlayIoTMotors.M1m},
            {text: 'M2+',value: PlayIoTMotors.M2p},
            {text: 'M2-',value: PlayIoTMotors.M2m}
        ];
    }

    /**
     * @return {array} - text and values for each gpio
     */
    get GPIO_MENU () {
        return [
            {text: 'GPIO0', value: PlayIoTGPIO.GPIO0},
            {text: 'GPIO1', value: PlayIoTGPIO.GPIO1},
            {text: 'GPIO2', value: PlayIoTGPIO.GPIO2},
            {text: 'GPIO3', value: PlayIoTGPIO.GPIO3}
        ];
    }


    constructor (runtime) {
        this.runtime = runtime
        this._peripheral = new PlayIoT(runtime, Scratch3PlayIoTBlocks.EXTENSION_ID)
    }

    getInfo () {
        return {
            id: Scratch3PlayIoTBlocks.EXTENSION_ID,
            name: Scratch3PlayIoTBlocks.EXTENSION_NAME,
            blockIconURI: blockIconURI,
            menuIconURI: blockIconURI,
            showStatusButton: true,
            blocks: [
                /* Bloques creados por Ibraim, 12 Feb 2025
                */
                {
                    opcode: 'whenButtonPressed',
                    text: "al presional el botón [BTN]",
                    blockType: BlockType.HAT,
                    arguments: {
                        BTN: {
                            type: ArgumentType.STRING,
                            menu: 'buttons',
                            defaultValue: PlayIoTButtons.A
                        }
                    }
                },
                {
                    opcode: 'isButtonPressed',
                    text: formatMessage({
                        id: 'microbit.isButtonPressed',
                        default: '[BTN] button pressed?',
                        description: 'is the selected button on the micro:bit pressed?'
                    }),
                    blockType: BlockType.BOOLEAN,
                    arguments: {
                        BTN: {
                            type: ArgumentType.STRING,
                            menu: 'buttons',
                            defaultValue: PlayIoTButtons.A
                        }
                    }
                },
                '---',
                {
                    opcode: 'rpPotentiometer',
                    text: "valor del potenciometro",
                    blockType: BlockType.REPORTER,
                }, 
                {
                    opcode: 'rpJoystickX',
                    text: "valor joystick X",
                    blockType: BlockType.REPORTER
                },
                {
                    opcode: 'rpJoystickY',
                    text: "valor joystick Y",
                    blockType: BlockType.REPORTER
                },
                '---',
                {
                    opcode: 'cmLED',
                    text: "encender LED [LED]",
                    blockType: BlockType.COMMAND,
                    arguments: {
                        LED: {
                            type: ArgumentType.STRING,
                            menu: 'motors',
                            defaultValue: PlayIoTMotors.M1p
                        },
                    }
                },
                '---',  
                {
                    opcode: 'cmGPIO',
                    text: "encender GPIO [GPIO]",
                    blockType: BlockType.COMMAND,
                    arguments: {
                        GPIO: {
                            type: ArgumentType.STRING,
                            menu: 'gpios',
                            defaultValue: PlayIoTGPIO.GPIO0
                        },
                    }
                }, 
                {
                    opcode: 'rpGPIO',
                    text: "valor de GPIO [GPIO]",
                    blockType: BlockType.REPORTER,
                    arguments: {
                        GPIO: {
                            type: ArgumentType.STRING,
                            menu: 'gpios',
                            defaultValue: PlayIoTGPIO.GPIO0
                        },
                    }
                },          
                {
                    opcode: 'whenPinConnected',
                    text: formatMessage({
                        id: 'microbit.whenPinConnected',
                        default: 'when pin [PIN] connected',
                        description: 'when the pin detects a connection to Earth/Ground'

                    }),
                    blockType: BlockType.HAT,
                    arguments: {
                        PIN: {
                            type: ArgumentType.STRING,
                            menu: 'touchPins',
                            defaultValue: '0'
                        }
                    }
                },
            ],
            menus: {
                buttons: {
                    acceptReporters: true,
                    items: this.BUTTONS_MENU
                },
                motors: {
                    acceptReporters: true,
                    items: this.MOTORS_MENU
                },
                gpios: {
                    acceptReporters: true,
                    items: this.GPIO_MENU
                },
                pinState: {
                    acceptReporters: true,
                    items: this.PIN_STATE_MENU
                }
            }
        }
    }
	rpPotentiometer = () => this._peripheral.pot
    rpJoystickX = () => this._peripheral.joyx
    rpJoystickY = () => this._peripheral.joyy
    /**
     * Test whether the A or B button is pressed
     * @param {object} args - the block's arguments.
     * @return {boolean} - true if the button is pressed.
     */
    whenButtonPressed (args) {
        if (args.BTN === 'any') {
            return this._peripheral.buttonA | this._peripheral.buttonB;
        } else if (args.BTN === 'A') {
            return this._peripheral.buttonA;
        } else if (args.BTN === 'B') {
            return this._peripheral.buttonB;
        }
        return false;
    }
    /**
     * Test whether the A or B button is pressed
     * @param {object} args - the block's arguments.
     * @return {boolean} - true if the button is pressed.
     */
    isButtonPressed (args) {
        if (args.BTN === 'any') {
            return (this._peripheral.buttonA | this._peripheral.buttonB) !== 0;
        } else if (args.BTN === 'A') {
            return this._peripheral.buttonA !== 0;
        } else if (args.BTN === 'B') {
            return this._peripheral.buttonB !== 0;
        }
        return false;
    }
}
module.exports = Scratch3PlayIoTBlocks
